UPDATE public.email_templates SET body_html = $$<!DOCTYPE html><html dir="ltr" lang="en"><head><meta charset="UTF-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><meta name="x-apple-disable-message-reformatting"/></head><body style="margin:0;padding:24px 12px;background:#f4f3ef;font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td align="center"><table role="presentation" width="100%" style="max-width:560px" cellpadding="0" cellspacing="0"><tr><td style="background:#ffffff;border:1px solid #e9e6dd;border-radius:12px;padding:32px"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td align="center" style="padding-bottom:20px;border-bottom:1px solid #e9e6dd"><img src="{{logoUrl}}" alt="CS Executive Group" height="36" style="height:36px;width:auto;display:block"/></td></tr><tr><td style="padding-top:24px"><h1 style="margin:0 0 16px;font-size:20px;line-height:28px;color:#2b2b2b;font-weight:700">Thank you for your application</h1></td></tr><tr><td style="padding-bottom:16px"><p style="margin:0;font-size:14px;line-height:22px;color:#3f3f3f">Dear {{candidateName}},</p></td></tr><tr><td style="padding-bottom:16px"><p style="margin:0;font-size:14px;line-height:22px;color:#3f3f3f">Thank you for your interest in the <strong>{{jobTitle}}</strong> role at <strong>{{companyName}}</strong> and for taking the time to apply. After careful consideration, we've decided to move forward with other candidates for this position.</p></td></tr><tr><td style="padding-bottom:16px"><p style="margin:0;font-size:14px;line-height:22px;color:#3f3f3f">We appreciate the effort you put into your application and encourage you to apply for future roles that match your skills and experience.</p></td></tr><tr><td style="padding-bottom:16px"><p style="margin:0;font-size:14px;line-height:22px;color:#3f3f3f">Kind regards</p></td></tr></table></td></tr></table></td></tr></table></body></html>$$, body_text = $$THANK YOU FOR YOUR APPLICATION

Dear {{candidateName}},

Thank you for your interest in the {{jobTitle}} role at {{companyName}} and for taking the time to apply. After careful consideration, we've decided to move forward with other candidates for this position.

We appreciate the effort you put into your application and encourage you to apply for future roles that match your skills and experience.

Kind regards$$ WHERE template_key = 'application_unsuccessful';

